service.method:

SELECT
		  USER_ID
		, MENU_PROFILE_CODE
		, USER_TYPE
FROM
	SUSMT
WHERE
		HOUSE_CODE 		= ${HOUSE_CODE}
	AND COMPANY_CODE 	= ${COMPANY_CODE}	
	AND USER_ID 		= ${USER_ID}


UPDATE SUSMT
   SET
		  CHANGE_DATE    	= ${current.DATE}
		, CHANGE_TIME    	= ${current.TIME}
		, CHANGE_USER_ID  	= ${session.ID}				  
		, USER_NAME_LOC	 	= ${USER_NAME_LOC}
		, DEPT		      	= ${DEPT}
		, POSITION		  	= ${POSITION}
		, EMAIL  		    = ${EMAIL}
		, PHONE           	= ${PHONE}
		, employee_no       = ${EMPLOYEE_NO}
		, DEL_FLAG        	= ${DEL_FLAG}
		, LANGUAGE			= 'KO'
		, USER_TYPE			= #DB_OWNER#nvl($S{USER_TYPE}, USER_TYPE)
		, RESPONSIBILITY    = ${RESPONSIBILITY}
WHERE
	  HOUSE_CODE        	= ${HOUSE_CODE}
  AND COMPANY_CODE 			= ${COMPANY_CODE}
  AND USER_ID           	= ${USER_ID}


INSERT INTO SUSMT
	(
		  HOUSE_CODE
		, USER_ID 
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID
		, COMPANY_CODE
		, PLANT_CODE
		, USER_NAME_LOC
		, PASSWORD
		, DEPT
		, POSITION
		, EMAIL		
		, COUNTRY
		, SIGN_STATUS
		, WORK_TYPE
		, MENU_PROFILE_CODE
		, USER_TYPE
		, PASS_CHECK_CNT
		, PW_RESET_FLAG
		, DEL_FLAG
		, DATE_FORMAT
		, PHONE
		, LANGUAGE
		, EMPLOYEE_NO
		, RESPONSIBILITY
	)
	VALUES
	(
		  ${HOUSE_CODE}
		, ${USER_ID}
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}
		, ${COMPANY_CODE}
		, ${COMPANY_CODE}
		, ${USER_NAME_LOC}
		, ${PASSWORD}
		, ${DEPT}
		, ${POSITION}
		, ${EMAIL}				
		, 'KR'
		, 'A'
		, 'G'
		, ${MENU_PROFILE_CODE}
		, 'A'
		, '0'
		, 'N'
		, ${DEL_FLAG}
		, '%Y/%m/%d'
		, ${PHONE}
		, 'KO'
		, ${EMPLOYEE_NO}
		, ${RESPONSIBILITY}
	)


UPDATE SBUPI
SET  
     USER_NAME          = ${USER_NAME_LOC}
    ,EMAIL              = ${EMAIL}
    ,PHONE_NO           = ${PHONE}
    ,DEL_FLAG           = ${DEL_FLAG}
    ,CHANGE_DATE        = ${current.DATE}
    ,CHANGE_TIME        = ${current.TIME}
    ,CHANGE_USER_ID     = ${session.ID}
WHERE
    HOUSE_CODE = ${session.HOUSE_CODE}
    AND BIZ_CODE = ${COMPANY_CODE}
    AND USER_ID = ${USER_ID}
